def transfer_projection(document):
 result=correction_projection(document);paths=result['paths'];schemas=result['components']['schemas']
 if not any(n in paths for n in PATHS) and not any(n in schemas for n in SCHEMAS):return result
 for section,pins in [(paths,PATHS),(schemas,SCHEMAS)]:
  for name,pin in pins.items():
   if digest(section.pop(name,None))!=pin:raise ValueError('Exact Q transfer transport required: '+name)
